/* Clip before indexing. Widen the sums to avoid signed-int overflow. */
int64_t left = x;
int64_t top = y;
int64_t right = (int64_t)x + w;
int64_t bottom = (int64_t)y + h;

if(left < 0) left = 0;
if(top < 0) top = 0;
if(right > SCREEN_WIDTH) right = SCREEN_WIDTH;
if(bottom > SCREEN_HEIGHT) bottom = SCREEN_HEIGHT;
if(left >= right || top >= bottom) return;

x = (int)left;
y = (int)top;
w = (int)(right - left);
h = (int)(bottom - top);
int *buf = _begin_draw(x, y, w, h);

for(int row = y; row < y + h; ++row) {
    int *pixel = buf + row * SCREEN_WIDTH + x;
    for(int column = 0; column < w; ++column) {
        pixel[column] = color;
    }
}
return;

int64_t dx = (int64_t)x2 - x1;
int64_t dy = (int64_t)y2 - y1;
int steep = llabs(dy) > llabs(dx);

    /* Use the longer axis, ordered consistently for reversed endpoints. */
    int64_t major1 = steep ? y1 : x1;
    int64_t major2 = steep ? y2 : x2;
    int64_t minor1 = steep ? x1 : y1;
    int64_t minor2 = steep ? x2 : y2;
    if(major1 > major2) {
        int64_t temporary = major1;
        major1 = major2;
        major2 = temporary;
        temporary = minor1;
        minor1 = minor2;
        minor2 = temporary;
    }

    uint64_t length = (uint64_t)(major2 - major1);
    if(length == 0) {
        fb_draw_pixel(x1, y1, color);
        return;
    }

    int direction = minor2 < minor1 ? -1 : 1;
    uint64_t minor_distance = (uint64_t)llabs(minor2 - minor1);
    int64_t limit = steep ? SCREEN_HEIGHT : SCREEN_WIDTH;
    int64_t first = major1 < 0 ? 0 : major1;
    int64_t last = major2 >= limit ? limit - 1 : major2;
    if(first > last) return;

    /*
     * Integer error accumulation, rounded to the nearest pixel.
     * Preserve the error phase when skipping off-screen major coordinates.
     * For 32-bit int endpoints, this product and sum fit in uint64_t.
     * The loop visits at most SCREEN_WIDTH or SCREEN_HEIGHT coordinates.
     */
    uint64_t numerator = minor_distance * (uint64_t)(first - major1)
                       + length / 2;
    int64_t minor = minor1 + direction * (int64_t)(numerator / length);
    uint64_t remainder = numerator % length;

    for(int64_t major = first; major <= last; ++major) {
        if(steep) {
            fb_draw_pixel((int)minor, (int)major, color);
        } else {
            fb_draw_pixel((int)major, (int)minor, color);
        }
        remainder += minor_distance;
        if(remainder >= length) {
            remainder -= length;
            minor += direction;
        }
    }
    return;
}

/* Blend one channel over an opaque framebuffer, with exact 0/255 endpoints. */
static unsigned blend_channel(unsigned src, unsigned dst, unsigned alpha)
{
    return (src * alpha + dst * (255-alpha) + 127) / 255;

if(!image || !image->content || image->pixel_w <= 0 || image->pixel_h <= 0) return;
int bytes = image->color_type == FB_COLOR_ALPHA_8 ? 1 : 4;
if(image->color_type != FB_COLOR_RGB_8880 &&
   image->color_type != FB_COLOR_RGBA_8888 &&
   image->color_type != FB_COLOR_ALPHA_8) return;
if(image->line_byte <= 0 || (int64_t)image->pixel_w * bytes > image->line_byte) return;

int64_t left = x, top = y;
int64_t right = (int64_t)x + image->pixel_w;
int64_t bottom = (int64_t)y + image->pixel_h;
if(left < 0) left = 0;
if(top < 0) top = 0;
if(right > SCREEN_WIDTH) right = SCREEN_WIDTH;
if(bottom > SCREEN_HEIGHT) bottom = SCREEN_HEIGHT;
if(left >= right || top >= bottom) return;
int ix = (int)(left-x), iy = (int)(top-y);
int w = (int)(right-left), h = (int)(bottom-top);
int *buf = _begin_draw((int)left, (int)top, w, h);
const unsigned char *source = (const unsigned char *)image->content
    + (size_t)iy * image->line_byte + (size_t)ix * bytes;
uint32_t foreground = (uint32_t)color;

for(int row = 0; row < h; ++row) {
    uint32_t *dst = (uint32_t *)(buf + ((int)top+row)*SCREEN_WIDTH + (int)left);
    const unsigned char *src = source + (size_t)row * image->line_byte;
    if(image->color_type == FB_COLOR_RGB_8880) {
        memcpy(dst, src, (size_t)w * 4);
        continue;
    }
    for(int column = 0; column < w; ++column) {
        unsigned alpha, b, g, r;
        if(bytes == 1) {
            alpha = src[column];
            b = foreground & 255; g = (foreground >> 8) & 255; r = (foreground >> 16) & 255;
        } else {
            const unsigned char *p = src + column*4;
            b = p[0]; g = p[1]; r = p[2]; alpha = p[3];
        }
        if(alpha == 0) continue;
        if(alpha != 255) {
            uint32_t old = dst[column];
            b = blend_channel(b, old & 255, alpha);
            g = blend_channel(g, (old >> 8) & 255, alpha);
            r = blend_channel(r, (old >> 16) & 255, alpha);
        }
        dst[column] = UINT32_C(0xff000000) | (r << 16) | (g << 8) | b;
    }
}

/* Cache rendered glyphs for any text/size. Returned images remain caller-owned.
 * Round-robin eviction bounds retained bitmap data to 64 * 64 KiB.
 * Failed cache allocations simply fall back to normal FreeType rendering.
 */
#define GLYPH_CACHE_COUNT 64
#define GLYPH_CACHE_MAX_BYTES (64U * 1024U)
static struct glyph_cache_entry {
	FT_Face face;
	FT_ULong codepoint;
	int pixel_size;
	fb_font_info info;
	fb_image *image;
} glyph_cache[GLYPH_CACHE_COUNT];
static unsigned glyph_cache_next;

static fb_image *copy_glyph_image(const fb_image *source)
{
	fb_image *copy = fb_new_image(source->color_type, source->pixel_w,
		source->pixel_h, source->line_byte);
	if(copy && source->pixel_h && source->line_byte)
		memcpy(copy->content, source->content,
			(size_t)source->pixel_h * source->line_byte);
	return copy;
}

for(unsigned entry = 0; entry < GLYPH_CACHE_COUNT; ++entry) {
	struct glyph_cache_entry *cached = &glyph_cache[entry];
	if(cached->image && cached->face == face &&
	   cached->codepoint == ucs4 && cached->pixel_size == pixel_size) {
		fb_image *copy = copy_glyph_image(cached->image);
		if(copy) {
			if(info) { *info = cached->info; info->bytes = sinfo.bytes; }
			return copy;
		}
		break;
	}
}

FT_Error error = FT_Set_Pixel_Sizes(face, 0, pixel_size);
if(error){
	printf("FT_Set_Pixel_Sizes: error %d\n", error);
	return NULL;
}

if((size_t)image->pixel_h * image->line_byte <= GLYPH_CACHE_MAX_BYTES) {
	fb_image *copy = copy_glyph_image(image);
	if(copy) {
		struct glyph_cache_entry *cached = &glyph_cache[glyph_cache_next];
		fb_free_image(cached->image);
		*cached = (struct glyph_cache_entry){face, ucs4, pixel_size, sinfo, copy};
		glyph_cache_next = (glyph_cache_next + 1) % GLYPH_CACHE_COUNT;
	}
}

#include "touch_protocol.h"
#include <linux/input.h>
#include <sys/ioctl.h>
#include <dirent.h>

static touch_state state;
static struct input_absinfo x_axis, y_axis;
static int dropped;

static int open_touch(const char *path)
{
    int fd = open(path, O_RDONLY | O_NONBLOCK);
    struct input_absinfo slot;
    if(fd < 0) return -1;
    if(ioctl(fd, EVIOCGABS(ABS_MT_SLOT), &slot) < 0 || slot.minimum != 0 ||
       ioctl(fd, EVIOCGABS(ABS_MT_POSITION_X), &x_axis) < 0 ||
       ioctl(fd, EVIOCGABS(ABS_MT_POSITION_Y), &y_axis) < 0 ||
       x_axis.maximum <= x_axis.minimum || y_axis.maximum <= y_axis.minimum) {
        close(fd);
        errno = ENODEV;
        return -1;
    }
    printf("touch device: %s, x=[%d,%d], y=[%d,%d], slots=%d\n", path,
           x_axis.minimum, x_axis.maximum, y_axis.minimum, y_axis.maximum,
           slot.maximum + 1);
    touch_state_init(&state);
    dropped = 0;
    return fd;
}

if(dev && *dev) {
    int fd = open_touch(dev);
    if(fd < 0) fprintf(stderr, "touch_init %s: %s\n", dev, strerror(errno));
    return fd;
}
DIR *dir = opendir("/dev/input");
if(!dir) { perror("/dev/input"); return -1; }
struct dirent *entry;
int fd = -1;
while((entry = readdir(dir)) != NULL) {
    if(strncmp(entry->d_name, "event", 5) != 0) continue;
    char path[512];
    snprintf(path, sizeof(path), "/dev/input/%s", entry->d_name);
    fd = open_touch(path);
    if(fd >= 0) break;
}
closedir(dir);
if(fd < 0) fprintf(stderr, "No protocol-B touchscreen found; use --touch /dev/input/eventN.\n");
return fd;

touch_sample sample;
for(;;) {
    if(touch_state_pop(&state, &sample)) {
        *x = sample.x; *y = sample.y; *finger = sample.finger;
        return sample.type;
    }
    struct input_event event;
    ssize_t n = read(fd, &event, sizeof(event));
    if(n < 0 && errno == EINTR) continue;
    if(n < 0 && (errno == EAGAIN || errno == EWOULDBLOCK)) return TOUCH_NO_EVENT;
    if(n != (ssize_t)sizeof(event)) {
        fprintf(stderr, "touch read stopped: %s\n", n == 0 ? "device closed" : strerror(errno));
        return TOUCH_ERROR;
    }
    if(event.type == EV_SYN && event.code == SYN_DROPPED) {
        dropped = 1;
        touch_state_init(&state);
        continue;
    }
    if(dropped) {
        if(event.type == EV_SYN && event.code == SYN_REPORT) {
            fprintf(stderr, "Touch events overflowed; restart the experiment to resynchronize.\n");
            return TOUCH_ERROR;
        }
        continue;
    }
    if(event.type == EV_ABS) {
        switch(event.code) {
        case ABS_MT_SLOT: touch_state_slot(&state, event.value); break;
        case ABS_MT_TRACKING_ID: touch_state_tracking(&state, event.value); break;
        case ABS_MT_POSITION_X:
            touch_state_position(&state, 0, touch_scale_axis(event.value,
                x_axis.minimum, x_axis.maximum, SCREEN_WIDTH)); break;
        case ABS_MT_POSITION_Y:
            touch_state_position(&state, 1, touch_scale_axis(event.value,
                y_axis.minimum, y_axis.maximum, SCREEN_HEIGHT)); break;
        }
    } else if(event.type == EV_SYN && event.code == SYN_REPORT) {
        touch_state_sync(&state);
    }
}

#include "touch_protocol.h"

void touch_state_init(touch_state *s)
{
    memset(s, 0, sizeof(*s));
    for(int i = 0; i < FINGER_NUM_MAX; ++i)
        s->slots[i].tracking = s->slots[i].old_tracking = -1;
}

void touch_state_slot(touch_state *s, int slot)
{
    /* Ignore every update for an unsupported slot, rather than corrupt slot 0. */
    s->slot = slot >= 0 && slot < FINGER_NUM_MAX ? slot : -1;
}

void touch_state_tracking(touch_state *s, int tracking)
{
    if(s->slot < 0) return;
    touch_slot *p = &s->slots[s->slot];
    p->tracking = tracking >= 0 ? tracking : -1;
    p->changed = 1;
}

void touch_state_position(touch_state *s, int is_y, int value)
{
    if(s->slot < 0) return;
    touch_slot *p = &s->slots[s->slot];
    if(is_y) p->y = value; else p->x = value;
    p->changed = 1;
}

static void append(touch_state *s, int type, int x, int y, int finger)
{
    s->ready[s->count++] = (touch_sample){type, x, y, finger};
}

void touch_state_sync(touch_state *s)
{
    /* Caller drains ready samples before feeding another complete frame. */
    s->count = s->next = 0;
    for(int i = 0; i < FINGER_NUM_MAX; ++i) {
        touch_slot *p = &s->slots[i];
        if(p->old_tracking >= 0 && p->tracking != p->old_tracking)
            append(s, TOUCH_RELEASE, p->old_x, p->old_y, i);
        if(p->tracking >= 0) {
            if(p->tracking != p->old_tracking)
                append(s, TOUCH_PRESS, p->x, p->y, i);
            else if(p->changed && (p->x != p->old_x || p->y != p->old_y))
                append(s, TOUCH_MOVE, p->x, p->y, i);
        }
        p->old_tracking = p->tracking;
        p->old_x = p->x;
        p->old_y = p->y;
        p->changed = 0;
    }
}

int touch_state_pop(touch_state *s, touch_sample *out)
{
    if(s->next == s->count) return 0;
    *out = s->ready[s->next++];
    return 1;
}

int touch_scale_axis(int value, int minimum, int maximum, int pixels)
{
    if(pixels <= 1 || maximum <= minimum || value <= minimum) return 0;
    if(value >= maximum) return pixels - 1;
    return (int)(((int64_t)value - minimum) * (pixels - 1) /
                 ((int64_t)maximum - minimum));
}

#ifndef TOUCH_PROTOCOL_H
#define TOUCH_PROTOCOL_H
#include "common.h"

/* Protocol B state, independent of Linux read/ioctl for offline replay. */
typedef struct { int type, x, y, finger; } touch_sample;
typedef struct {
    int x, y, tracking, old_tracking, old_x, old_y, changed;
} touch_slot;
typedef struct {
    touch_slot slots[FINGER_NUM_MAX];
    touch_sample ready[FINGER_NUM_MAX * 2];
    int slot, count, next;
} touch_state;
void touch_state_init(touch_state *s);
void touch_state_slot(touch_state *s, int slot);
void touch_state_tracking(touch_state *s, int tracking);
void touch_state_position(touch_state *s, int is_y, int value);
void touch_state_sync(touch_state *s);
int touch_state_pop(touch_state *s, touch_sample *out);
int touch_scale_axis(int value, int minimum, int maximum, int pixels);
#endif

#include "../common/common.h"
#include "drawing.h"

#define TOOLBAR_H 64
#define CLEAR_X (SCREEN_WIDTH - 140)
#define RADIUS 4
#define BACKGROUND FB_COLOR(255,255,255)
static const int colors[FINGER_NUM_MAX] = {
    FB_COLOR(230,40,40), FB_COLOR(20,110,230), FB_COLOR(20,155,65),
    FB_COLOR(170,60,200), FB_COLOR(245,145,10)
};
static struct { int down, active, suppressed, x, y; } pens[FINGER_NUM_MAX];

static void clear_canvas(void)
{
    fb_draw_rect(0, 0, SCREEN_WIDTH, SCREEN_HEIGHT, BACKGROUND);
    fb_draw_rect(0, 0, SCREEN_WIDTH, TOOLBAR_H, FB_COLOR(235,240,245));
    fb_draw_text(16, 40, "五指画板", 28, FB_COLOR(25,35,50));
    for(int i = 0; i < FINGER_NUM_MAX; ++i)
        fb_draw_rect(220 + i * 40, 22, 24, 24, colors[i]);
    fb_draw_rect(CLEAR_X, 0, 140, TOOLBAR_H, FB_COLOR(215,225,235));
    fb_draw_border(CLEAR_X, 0, 140, TOOLBAR_H, FB_COLOR(60,70,80));
    fb_draw_text(CLEAR_X + 22, 41, "清屏", 28, FB_COLOR(25,35,50));
}

static void stamp(int x, int y, int color)
{
    for(int dy = -RADIUS; dy <= RADIUS; ++dy)
        for(int dx = -RADIUS; dx <= RADIUS; ++dx)
            if(dx*dx + dy*dy <= RADIUS*RADIUS && y+dy >= TOOLBAR_H)
                fb_draw_pixel(x+dx, y+dy, color);
}

static void stroke(int x0, int y0, int x1, int y1, int color)
{
    /* Stamp along every Bresenham point; fast motion remains connected. */
    int dx = abs(x1-x0), sx = x0 < x1 ? 1 : -1;
    int dy = -abs(y1-y0), sy = y0 < y1 ? 1 : -1;
    int error = dx+dy;
    for(;;) {
        stamp(x0, y0, color);
        if(x0 == x1 && y0 == y1) break;
        int twice = 2*error;
        if(twice >= dy) { error += dy; x0 += sx; }
        if(twice <= dx) { error += dx; y0 += sy; }
    }
}

void lab4_canvas_init(void)
{
    memset(pens, 0, sizeof(pens));
    clear_canvas();
}

void lab4_canvas_event(int type, int x, int y, int finger)
{
    if(finger < 0 || finger >= FINGER_NUM_MAX ||
       x < 0 || x >= SCREEN_WIDTH || y < 0 || y >= SCREEN_HEIGHT) return;
    if(type == TOUCH_PRESS) {
        pens[finger].down = 1;
        pens[finger].active = pens[finger].suppressed = 0;
        if(x >= CLEAR_X && y < TOOLBAR_H) {
            for(int i = 0; i < FINGER_NUM_MAX; ++i) {
                pens[i].suppressed = pens[i].down;
                pens[i].active = 0;
            }
            clear_canvas();
            return;
        }
    }
    if((type == TOUCH_PRESS || type == TOUCH_MOVE || type == TOUCH_RELEASE) &&
       pens[finger].down && !pens[finger].suppressed) {
        if(y >= TOOLBAR_H) {
            if(pens[finger].active)
                stroke(pens[finger].x, pens[finger].y, x, y, colors[finger]);
            else stamp(x, y, colors[finger]);
            pens[finger].x = x; pens[finger].y = y;
            pens[finger].active = 1;
        } else pens[finger].active = 0;
    }
    if(type == TOUCH_RELEASE) {
        pens[finger].down = pens[finger].active = pens[finger].suppressed = 0;
    }
}

